# groovy_utils — MCP server generated by mcp-forge
# This MCP server exposes Groovy utility functions for common mathematical and string operations, including prime checking, factorial calculation, string reversal, and list summation.
#
# Auto-generated — edit as needed.
# IMPORTANT : ce serveur appelle des fonctions Groovy via subprocess.
#             Assurez-vous que 'groovy' est installé et accessible dans votre PATH.
#             Le fichier source est exécuté tel quel (fonction/appel ajoutés à la
#             suite) : les imports/dépendances entre plusieurs fichiers source
#             ne sont pas résolus, seul le fichier contenant la fonction l'est.
# To run: python server.py
# To test: mcp dev server.py

from __future__ import annotations

import os
from contextvars import ContextVar

import json
import shutil
import subprocess
import tempfile

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("groovy_utils")

_request_token: ContextVar[str] = ContextVar("_request_token", default="")

# Redéfinissable via variable d'environnement pour un déploiement hors de la
# machine où le serveur a été généré (le chemin par défaut ne fonctionnera
# que sur cette machine).
SCRIPT_SOURCE_DIR = os.environ.get("GROOVY_SOURCE_DIR", os.path.join(os.path.dirname(os.path.abspath(__file__)), "source"))


def _interpreter_available() -> bool:
    return shutil.which("groovy") is not None


def _run_script(script_file: str, call_expr: str) -> str:
    """Exécute `call_expr` après avoir injecté le fichier source `script_file`
    dans un driver temporaire. Logique commune à tous les outils de ce
    serveur — extraite ici pour éviter de la répéter dans chaque fonction
    `@mcp.tool` (répétition signalée par l'évaluateur qualité sur plusieurs
    langages avant cette extraction)."""
    if not _interpreter_available():
        return "Erreur : interpréteur 'groovy' introuvable dans le PATH."

    source_path = os.path.join(SCRIPT_SOURCE_DIR, script_file)
    try:
        with open(source_path, encoding="utf-8") as f:
            source_code = f.read()
    except OSError as exc:
        return f"Erreur : impossible de lire {source_path} ({exc})"
    # Le fichier source est exécuté en entier puis l'appel est ajouté à la
    # suite : les définitions de fonctions du fichier original sont donc
    # visibles au moment de l'appel, sans dépendre d'un mécanisme d'export
    # spécifique au langage (module.exports, etc.).
    driver = source_code + "\n" + "println(" + call_expr + ")" + "\n"

    tmp_path = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".groovy", delete=False, encoding="utf-8"
        ) as tmp:
            tmp.write(driver)
            tmp_path = tmp.name
        result = subprocess.run(
            ["groovy", tmp_path],
            capture_output=True, text=True, timeout=10,
            # Sur Windows, certains interpréteurs (ex: Dart via Flutter)
            # s'installent comme un script .bat/.cmd, pas un .exe — un appel
            # sans shell échoue avec WinError 193/2 même si shutil.which()
            # l'a trouvé. shell=True laisse cmd.exe résoudre l'extension via
            # PATHEXT. Sur POSIX, shell=True avec une liste traite les
            # éléments après le premier comme des arguments du SHELL lui-même
            # (pas de la commande) — on ne l'active donc que sous Windows.
            shell=(os.name == "nt"),
        )
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass

    if result.returncode != 0:
        return f"Erreur Groovy : {result.stderr.strip() or result.stdout.strip()}"
    return result.stdout.strip()


def _to_literal(value: object) -> str:
    """Formate une valeur Python en littéral Groovy valide."""
    if value is None:
        # json.dumps(None) -> "null", invalide ou sémantiquement faux dans
        # la plupart des langages de ce groupe (Lua: nil, Elixir/Ruby: nil,
        # R: NULL, PowerShell: $null) — valeur possible pour un paramètre
        # optionnel de type liste/objet sans valeur fournie.
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace("'", "\\'")
        return "'" + escaped + "'"
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(_to_literal(v) for v in value) + "]"
    return json.dumps(value)

@mcp.tool(name="check_isprime")
def check_isprime(
    n: int,
) -> str:
    """Determine whether a number is prime. Use this to check if a given integer has exactly two divisors (1 and itself).
    Args:
        n: The integer to check for primality. Must be a positive integer.
    Returns:
        Résultat de la fonction Groovy.
    """
    _call_values = [n]
    _literal_parts = [_to_literal(_v) for _v in _call_values]
    call_args = ", ".join(_literal_parts)
    call_expr = "isPrime(" + call_args + ")"
    return _run_script("Utils.groovy", call_expr)

@mcp.tool(name="calculate_factorial")
def calculate_factorial(
    n: int,
) -> str:
    """Calculate the factorial of a non-negative integer. Use this to compute n! (the product of all positive integers up to n).
    Args:
        n: Non-negative integer for which to calculate the factorial.
    Returns:
        Résultat de la fonction Groovy.
    """
    _call_values = [n]
    _literal_parts = [_to_literal(_v) for _v in _call_values]
    call_args = ", ".join(_literal_parts)
    call_expr = "factorial(" + call_args + ")"
    return _run_script("Utils.groovy", call_expr)

