@mcp.tool(name="sum_list")
def sum_list(
    numbers: list,
) -> str:
    """Calculate the sum of all numeric values in a list. Use this to aggregate numbers from a collection.
    Args:
        numbers: Array of numeric values (integers or decimals) to sum.
    Returns:
        Résultat de la fonction Groovy.
    """
    _call_values = [numbers]
    _literal_parts = [_to_literal(_v) for _v in _call_values]
    call_args = ", ".join(_literal_parts)
    call_expr = "sumList(" + call_args + ")"
    return _run_script("Utils.groovy", call_expr)


